// Form A: live Q heads rotated (or copied) into q_out, pad heads zero-filled, KV row inserted; q_inplace rotates the
// 64 rope dims of q itself (q_out == q, q_head_padded == heads, apply_q_rope) with one Q warp per 8 heads.  Dispatch
// key (q_head_padded, apply_q_rope, slot dtype, q_inplace); the live head count travels in a.num_heads_q.
cudaError_t launch_qkv(const KernelArgs& a, int q_head_padded, bool apply_q_rope, bool slot_int64, bool q_inplace,
                       dim3 grid, cudaStream_t stream) {
