// Form B: KV only, compressed-pool boundary rule.  Dispatch key (compress_ratio, slot dtype); a.q / a.q_out are
// null and a.num_heads_q is 0.
cudaError_t launch_kv(const KernelArgs& a, int compress_ratio, bool slot_int64, dim3 grid, cudaStream_t stream) {
  if (compress_ratio == 1 && slot_int64) {
    kv_r1_s64::kernel_flashinfer_sm120_dsv4_nvfp4_rope_insert_kv_r1_s64<<<grid, kThreads, 0, stream>>>(a.q, a.kv, a.cache, a.slot_mapping_i64, a.slot_mapping_i32, a.positions, a.cos_sin, a.q_out, a.num_tokens, a.num_tokens_insert, a.num_heads_q, a.page_size, a.page_stride_bytes, a.total_slots);
    return cudaGetLastError();
  }
  if (compress_ratio == 2 && slot_int64) {
    kv_r2_s64::kernel_flashinfer_sm120_dsv4_nvfp4_rope_insert_kv_r2_s64<<<grid, kThreads, 0, stream>>>(a.q, a.kv, a.cache, a.slot_mapping_i64, a.slot_mapping_i32, a.positions, a.cos_sin, a.q_out, a.num_tokens, a.num_tokens_insert, a.num_heads_q, a.page_size, a.page_stride_bytes, a.total_slots);
    return cudaGetLastError();
  }
  if (compress_ratio == 1 && !slot_int64) {
    kv_r1_s32::kernel_flashinfer_sm120_dsv4_nvfp4_rope_insert_kv_r1_s32<<<grid, kThreads, 0, stream>>>(a.q, a.kv, a.cache, a.slot_mapping_i64, a.slot_mapping_i32, a.positions, a.cos_sin, a.q_out, a.num_tokens, a.num_tokens_insert, a.num_heads_q, a.page_size, a.page_stride_bytes, a.total_slots);
    return cudaGetLastError();
  }
  if (compress_ratio == 2 && !slot_int64) {
    kv_r2_s32::kernel_flashinfer_sm120_dsv4_nvfp4_rope_insert_kv_r2_s32<<<grid, kThreads, 0, stream>>>(a.q, a.kv, a.cache, a.slot_mapping_i64, a.slot_mapping_i32, a.positions, a.cos_sin, a.q_out, a.num_tokens, a.num_tokens_insert, a.num_heads_q, a.page_size, a.page_stride_bytes, a.total_slots);
    return cudaGetLastError();
  }
  return cudaErrorInvalidValue;
}

